import socket, concurrent.futures
def scan(host):
    open_ports=[]
    def chk(p):
        s=socket.socket(); s.settimeout(0.5)
        try:
            s.connect((host,p)); return p
        except: return None
        finally: s.close()
    with concurrent.futures.ThreadPoolExecutor(400) as ex:
        for r in ex.map(chk, range(1,65536)):
            if r: open_ports.append(r)
    return open_ports
for host in ['172.25.0.2','172.25.0.3','172.25.0.1']:
    print(host, scan(host))
EOF"}

